"""餐饮与住宿领域人工编写场景；程序只组装协议及执行检查。"""
import json
import subprocess
import sys
from collections import Counter
from pathlib import Path

from openjev.data import CASE_TYPES, write_jsonl, validate_shards, question_records
from openjev.model import get_tokenizer, encode_candidates
from openjev.protocol import parse_request

ROOT = Path(__file__).resolve().parents[2]
TOPICS = {}


def C(state, instruction, criteria, values, evidence):
    return state, {"type": "choice", "instructions": instruction, "criteria": criteria}, {"probabilities": dict(zip(criteria, values))}, evidence


def S(state, instruction, criteria, values, evidence):
    return state, {"type": "score", "instructions": instruction, "criteria": criteria}, {"probabilities": dict(zip(map(str, range(len(criteria))), values))}, evidence


def N(state, instruction, value, evidence):
    return state, {"type": "noul", "instructions": instruction}, {"noul": value}, evidence


def M(state, choice, score, noul):
    return state, {"分类": choice[1], "程度": score[1], "命题": noul[1]}, {"分类": choice[2], "程度": score[2], "命题": noul[2]}, {"分类": choice[3], "程度": score[3], "命题": noul[3]}


def add(number, rows):
    assert len(rows) == 10
    tid = f"T{number:04d}"
    result = []
    for slot, (state, question, label, evidence) in enumerate(rows, 1):
        if slot == 1:
            if isinstance(state, str):
                state = {"现场记录": state}
            if isinstance(question["instructions"], str):
                question["instructions"] = {"判断任务": question["instructions"], "证据范围": "仅依据此记录中的对象与有效时间，不补入未给出的规则。"}
            first = next(iter(question["criteria"]))
            if isinstance(question["criteria"][first], str):
                question["criteria"][first] = {"含义": question["criteria"][first]}
        if slot == 10:
            questions, labels, evidences = question, label, evidence
        else:
            qid = {"choice": "分类", "score": "程度", "noul": "命题"}[question["type"]]
            questions, labels, evidences = {qid: question}, {qid: label}, {qid: evidence}
        result.append({"sample_id": f"{tid}-{slot:02d}", "topic_id": tid, "slot": slot,
                       "request": {"model": "jev-latest", "state": state, "questions": questions},
                       "labels": labels, "review": {"case_type": CASE_TYPES[slot], "evidence": evidences, "label_source": "agent_synthetic"}})
    TOPICS[tid] = result


