def main():
    if "--audit-only" not in sys.argv:
        for tid, rows in TOPICS.items():
            destination = ROOT / "data/shards" / f"{tid}.jsonl"
            if destination.exists():
                raise FileExistsError(f"不覆盖已有正式分片: {destination}")
        for tid, rows in TOPICS.items():
            path = ROOT / "data/drafts" / f"{tid}.jsonl"
            write_jsonl(path, rows)
            subprocess.run([sys.executable, "-m", "scripts.finalize_shard", str(path)], cwd=ROOT, check=True)
    paths = [ROOT / "data/shards" / f"T{i:04d}.jsonl" for i in range(21,41)]
    rows = validate_shards(paths)
    tokenizer = get_tokenizer(str(ROOT / "Qwen3.5-0.8B"))
    lengths = {}
    candidate_count = 0
    for r in question_records(rows):
        question = parse_request({"model":"local", "state":r["state"], "questions":{"q":r["question"]}}).questions["q"]
        encoded, _ = encode_candidates(tokenizer, r["state"], question, 8192)
        candidate_count += len(encoded["input_ids"])
        lengths[r["sample_id"]] = max(lengths.get(r["sample_id"],0), max(map(len,encoded["input_ids"])))
    def distribution(v):
        v = list(v)
        return {"short_up_to_1024":sum(x<=1024 for x in v), "medium_1025_to_4096":sum(1024<x<=4096 for x in v), "long_4097_to_8192":sum(4096<x<=8192 for x in v), "over_8192":sum(x>8192 for x in v)}
    report = {"topic_ids":[f"T{i:04d}" for i in range(21,41)], "requests":len(rows), "questions":len(question_records(rows)), "candidate_inputs":candidate_count, "max_tokens":max(lengths.values()), "length_distribution":distribution(lengths.values()), "domain_length_distribution":{name:distribution(v for k,v in lengths.items() if start<=int(k[1:5])<=end) for name,start,end in [("餐饮门店",21,30),("酒店住宿",31,40)]}, "request_max_tokens":lengths}
    report["validation"] = {"validate_shards":"passed_for_all_20_owned_shards", "length_method":"openjev.model.encode_candidates + local Qwen3.5-0.8B tokenizer; max_length=8192; truncation=False", "finalization":"All official shards published by scripts.finalize_shard", "label_source":"agent_synthetic", "training_started":False, "external_model_api_used":False}
    report["question_types"] = dict(Counter(q["type"] for r in rows for q in r["request"]["questions"].values()))
    report["format_coverage"] = {"object_states":sum(isinstance(r["request"]["state"],dict) for r in rows), "array_states":sum(isinstance(r["request"]["state"],list) for r in rows), "structured_instructions":sum(isinstance(q["instructions"],(dict,list)) for r in rows for q in r["request"]["questions"].values()), "structured_choice_descriptions":sum(isinstance(v,(dict,list)) for r in rows for q in r["request"]["questions"].values() if q["type"]=="choice" for v in q["criteria"].values()), "topics_with_structured_state":sum(any(isinstance(r["request"]["state"],(dict,list)) for r in rows if r["topic_id"]==tid) for tid in TOPICS)}
    report["choice_winning_positions_one_based"] = dict(Counter(str(list(q["criteria"]).index(r["response"]["answers"][qid]["choice"])+1) for r in rows for qid,q in r["request"]["questions"].items() if q["type"]=="choice"))
    report["mixed_unknown_noul_samples"] = [r["sample_id"] for r in rows if r["slot"]==10 and .35<=r["response"]["answers"]["命题"]["noul"]<=.65]
    report["semantic_review"] = {
        "reviewer":"authoring agent self-review; not an independent model review",
        "full_topics":["T0022","T0029","T0039","T0040"],
        "full_topic_findings":{
            "T0022":"十条分别核配方直接匹配、共线、声明缺失、误贴声明、三档流程及独立制作状态；所需规则自包含，不把安全判断推广为实际医学结论。修正07中档以免与零完成重叠。",
            "T0029":"十条均为指定说话者与用餐对象的情感；混合与缺失分开，引用及反讽限定本人当前态度，低档含事实中性陈述，否定有直接满意反证；混合Noul问实际结账满意度。",
            "T0039":"十条均为住客情感；担忧针对未来渗水、愤怒针对当前服务，未用事件本身推情绪；补足中性陈述与整体褒贬混合，未知Noul改为已发生但评价缺失的健身房体验。",
            "T0040":"十条区分咨询、计划、正式请求、撤回、他人意图及当前有效诉求；Score只衡量请求明确程度，三级互斥；否定续住为本人明确拒绝。"
        },
        "other_topic_boundary_samples":{tid:[f"{tid}-03",f"{tid}-09"] for tid in TOPICS if tid not in {"T0022","T0029","T0039","T0040"}},
        "other_topic_findings":"其余16题逐题检查03与09：03均缺决定性事实或适用规则，09均有具体反证而非未提及；额外修正T0038-09为明确10月日期。",
        "long_and_medium_samples":["T0023-04","T0024-10","T0035-10","T0037-10"],
        "long_and_medium_findings":"按对象与时点审查完整交接对话：烤箱故障不属于炒锅目标菜，旧库存不覆盖当前领料；客房作业完成不替代最终复检。预约时段更正、失物特征与交付是独立维度。内容未使用机械重复日志或命题编号补长。",
        "distinct_reviewed_requests":76,
        "checks":{"self_contained_rules":True,"ordered_score_dimensions":True,"explicit_negative_evidence":True,"quote_and_current_intent_scope":True,"per_question_independent_evidence":True,"no_topic_id_or_review_in_request":True,"substantively_distinct_ten_scenarios_per_topic":True},
        "corrected_before_delivery":["补足情感专项中性与住宿褒贬混合覆盖", "澄清不满程度与意图明确程度的互斥等级", "将未知情感Noul限定为实际态度，移除表达充分性歧义", "修正过敏提示Score中档与低档重叠", "酒店日期否定样本补全月份"],
        "unresolved_semantic_issues":[]
    }
    report["limitations"] = ["长度实际为196短、2中、2长；每领域至少一中一长已满足，但未达到建议的逐题7短2中1长。", "全部概率为agent_synthetic软标签，未由真实业务频率或外部教师校准。", "本报告只核本人负责20题的精确重复与跨split同state；全量跨领域复核交由主agent。"]
    report_path = ROOT / "reports/generation/domains_03_04.json"
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding="utf-8")
    print(json.dumps({k:v for k,v in report.items() if k in {"requests","questions","candidate_inputs","max_tokens","length_distribution","domain_length_distribution","format_coverage","question_types","choice_winning_positions_one_based"}},ensure_ascii=False))


if __name__ == "__main__":
    main()
